PLACE_SEGMENT) like \'%commerce%\' ; create or replace table `MapleMonk.zouk_Mens_collection_Secondary_Sales` as select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(COLLECTION) like \'%men%\' ; Create or replace table maplemonk.zouk_sales_consolidated_offline as select s.*, m.City as Store_City, m.Tier, m.State as Store_State, m.Region, m.Store_Type, m.City_Cluster, m.Store_Classification from maplemonk.zouk_sales_consolidated s left join `MapleMonk.Zouk_EBO_Store_Master` m on UPPER(s.Store_Code) = UPPER(m.Store_Code) AND lower(s.source) = lower(m.Store_Name) where (lower(MARKETPLACE_SEGMENT) like any (\'%offline%\',\'%ebo%\')) ; Create or replace table maplemonk.zouk_secondary_sales_consolidated_MP as select * from maplemonk.zouk_secondary_sales_consolidated where lower(MARKETPLACE_SEGMENT) like \'%commerce%\' ; Create or replace table maplemonk.zouk_pandl_offline as select * from maplemonk.zouk_pandl where lower(final_Marketplace) like any (\'%offline%\',\'ebo\') ; Create or replace table maplemonk.zouk_pandl_DTC as select * from maplemonk.zouk_pandl where (lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\')) ; Create or replace table maplemonk.zouk_pandl_MP as select * from maplemonk.zouk_pandl where not(lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\',\'%offline%\',\'ebo\')) ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Power_Potli_Data AS select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(PRODUCT_CATEGORY) like \'%power%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Luggage_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(COLLECTION) like \'%luggage%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Backpack_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE UPPER(PRODUCT_CATEGORY) LIKE ANY (\"CLASSIC BACKPACK\", \"STATEMENT BACKPACK\", \"OLINA DAYPACK\", \"DOME DAYPACK\", \"AMALIA DAYPACK\", \"AMALIA BACKPACK (LARGE)\", \"TAARAN BACKPACK\", \"CONSULTANT BACKPACK\", \"MAYRA MINI-DAYPACK\", \"DALILA MINI-DAYPACK\", \"CLASSIC DAYPACK\", \"LAPTOP BACKPACK\", \"OFFICE BACKPACK\") ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Lineitem_Pricing_Report AS SELECT NAME, Date(safe_cast(created_at as datetime)) As Created_At, JSON_EXTRACT_SCALAR(line_item_json, \'$.title\') AS LineItem_Name, JSON_EXTRACT_SCALAR(line_item_json, \'$.sku\') AS LineItem_SKU, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.price\') AS FLOAT64) AS LineItem_Price, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.quantity\') AS INT64) AS LineItem_Quantity FROM `zouk-wh.maplemonk.Shopify_zoukbags_ORDERS`, UNNEST(line_items) AS line_item_json ;",
